import SwiftUI

struct ContentView: View {
    @EnvironmentObject private var engine: SatHunterEngine
    var body: some View { TabView() { ReceiverView().tabItem { Label("Receptor", systemImage: "radio") }; SatellitesView().tabItem { Label("Satélites", systemImage: "satellite") }; SettingsView().tabItem { Label("Configurações", systemImage: "gearshape") } }.tint(.blue) }
}
private struct ReceiverView: View {
    @EnvironmentObject private var engine: SatHunterEngine
    var running: Bool { engine.status["running"] as? Bool ?? false }; var source: String { engine.status["source"] as? String ?? "desconhecida" }; var mode: String { engine.status["mode"] as? String ?? "WFM" }; var hz: Double { engine.status["vfo_hz"] as? Double ?? 0 }
    var body: some View { NavigationStack { ScrollView { VStack(alignment: .leading, spacing: 16) { HStack { Label("Receptor", systemImage: "antenna.radiowaves.left.and.right").font(.title2.bold()); Spacer(); Circle().fill(running ? .green : .red).frame(width: 12) }; Text("Fonte: \(source) • \(String(format: "%.3f MHz", hz / 1e6))").foregroundStyle(.secondary); HStack { Button(running ? "Parar" : "Iniciar") { running ? engine.stop() : engine.start() }.buttonStyle(.borderedProminent); Button("Usar demonstração") { engine.setSource("demo") }.buttonStyle(.bordered) }; Picker("Modo", selection: Binding(get: { mode }, set: { engine.setMode($0) })) { ForEach(["WFM","NFM","AM","USB","LSB","CW"], id: \.self) { Text($0).tag($0) } }.pickerStyle(.segmented); Text("Estado do núcleo").font(.headline); Text(engine.status["source_status"] as? String ?? (running ? "Executando" : "Parado")).frame(maxWidth: .infinity, alignment: .leading).padding().background(.thinMaterial).clipShape(RoundedRectangle(cornerRadius: 12)); if let err = engine.lastError { Text(err).foregroundStyle(.red) } }.padding() }.navigationTitle("SatHunter SDR") } }
}
private struct SatellitesView: View { @EnvironmentObject private var engine: SatHunterEngine; var body: some View { NavigationSplitView { List(engine.satelliteRows.indices, id: \.self) { i in let row = engine.satelliteRows[i]; let name = row["name"] as? String ?? "Satélite"; let norad = row["norad"] as? Int ?? 0; Button { engine.select(norad) } label: { VStack(alignment: .leading) { Text(name); Text("NORAD \(norad)").font(.caption).foregroundStyle(.secondary) } } }.navigationTitle("Satélites") } detail: { SatelliteDetailView() } } }
private struct SatelliteDetailView: View { @EnvironmentObject private var engine: SatHunterEngine; var body: some View { VStack(alignment: .leading, spacing: 12) { Text(engine.detail["name"] as? String ?? "Selecione um satélite").font(.title2.bold()); Text("Azimute: \(String(format: "%.1f°", engine.detail["az"] as? Double ?? 0)) • Elevação: \(String(format: "%.1f°", engine.detail["el"] as? Double ?? 0))"); Button("Começar rastreio") { engine.track(true) }.buttonStyle(.borderedProminent); Spacer() }.padding() } }
private struct SettingsView: View { @EnvironmentObject private var engine: SatHunterEngine; var body: some View { NavigationStack { Form { Section("Fonte") { Button("Demonstração") { engine.setSource("demo") }; Text("USB direto no iPad exige uma camada DriverKit ou fonte de rede.").font(.footnote).foregroundStyle(.secondary) }; Section("Diagnóstico") { Text("Satélites carregados: \(engine.satelliteRows.count)"); Text("Núcleo: \(engine.status.isEmpty ? "não inicializado" : "pronto")") } }.navigationTitle("Configurações") } } }
